static List<Vector2> Profile(){var p=new List<Vector2>{new Vector2(.798f,-2.641f),new Vector2(.798f,-2.740f),new Vector2(.730f,-2.740f),new Vector2(.730f,-2.724f),new Vector2(.746f,-2.724f),new Vector2(.746f,-2.674f)};for(int i=1;i<=10;i++){float a=(180-i*9)*Mathf.Deg2Rad;p.Add(new Vector2(.775f+Mathf.Cos(a)*.029f,-2.674f+Mathf.Sin(a)*.029f));}return p;}
static float Cross(Vector2 a,Vector2 b,Vector2 c)=>(b.x-a.x)*(c.y-a.y)-(b.y-a.y)*(c.x-a.x);
static bool InTriangle(Vector2 p,Vector2 a,Vector2 b,Vector2 c){float x=Cross(a,b,p),y=Cross(b,c,p),z=Cross(c,a,p);return (x>=-1e-8&&y>=-1e-8&&z>=-1e-8)||(x<=1e-8&&y<=1e-8&&z<=1e-8);}
static List<int> Cap(List<Vector2> p){var work=Enumerable.Range(0,p.Count).ToList();float area=0;for(int i=0;i<p.Count;i++)area+=p[i].x*p[(i+1)%p.Count].y-p[(i+1)%p.Count].x*p[i].y;if(area<0)work.Reverse();var result=new List<int>();int safety=0;while(work.Count>3&&safety++<1000){bool cut=false;for(int i=0;i<work.Count;i++){int a=work[(i+work.Count-1)%work.Count],b=work[i],c=work[(i+1)%work.Count];if(Cross(p[a],p[b],p[c])<=1e-8)continue;if(work.Any(n=>n!=a&&n!=b&&n!=c&&InTriangle(p[n],p[a],p[b],p[c])))continue;result.AddRange(new[]{a,b,c});work.RemoveAt(i);cut=true;break;}if(!cut)throw new Exception("Cannot triangulate formed jamb profile");}result.AddRange(work);return result;}
static Mesh Jamb(int side,Transform paint){var profile=Profile();var vertices=new List<Vector3>();var normals=new List<Vector3>();var uv=new List<Vector2>();var triangles=new List<int>();Action<Vector3,Vector3,Vector3,Vector3> tri=(a,b,c,n)=>{if(Vector3.Dot(Vector3.Cross(b-a,c-a),n)<0){var t=b;b=c;c=t;}int k=vertices.Count;foreach(var v in new[]{a,b,c}){vertices.Add(paint.InverseTransformPoint(v));normals.Add(paint.InverseTransformDirection(n));uv.Add(new Vector2(.10f+(Mathf.Abs(v.x)-.730f)*.15f,.41f+(v.y-.674f)*.18f));}triangles.AddRange(new[]{k,k+1,k+2});};
float low=.674f,high=1.128f;for(int i=0;i<profile.Count;i++){int j=(i+1)%profile.Count;var a=new Vector3(side*profile[i].x,low,profile[i].y);var b=new Vector3(side*profile[j].x,low,profile[j].y);var c=new Vector3(b.x,high,b.z);var d=new Vector3(a.x,high,a.z);var edge=profile[j]-profile[i];var n=new Vector3(side*-edge.y,0,edge.x).normalized; // Profile is clockwise; left normal points out.
tri(a,b,c,n);tri(a,c,d,n);}
var caps=Cap(profile);for(int i=0;i<caps.Count;i+=3){var a=profile[caps[i]];var b=profile[caps[i+1]];var c=profile[caps[i+2]];tri(new Vector3(side*a.x,high,a.y),new Vector3(side*b.x,high,b.y),new Vector3(side*c.x,high,c.y),Vector3.up);tri(new Vector3(side*a.x,low,a.y),new Vector3(side*b.x,low,b.y),new Vector3(side*c.x,low,c.y),Vector3.down);}
var mesh=new Mesh{name="Formed inner rear bed jamb "+side};mesh.SetVertices(vertices);mesh.SetNormals(normals);mesh.SetUVs(0,uv);mesh.SetTriangles(triangles,0);mesh.RecalculateBounds();mesh.RecalculateTangents();return mesh;}
static void ValidateClosed(Mesh mesh){var edges=new Dictionary<string,int>();var v=mesh.vertices;var t=mesh.triangles;for(int i=0;i<t.Length;i+=3)for(int e=0;e<3;e++){string a=v[t[i+e]].ToString("F6"),b=v[t[i+(e+1)%3]].ToString("F6");string k=string.CompareOrdinal(a,b)<0?a+"|"+b:b+"|"+a;edges.TryGetValue(k,out int count);edges[k]=count+1;}if(edges.Values.Any(n=>n!=2))throw new Exception("Open/nonmanifold jamb edge");report.AppendLine("CLOSED "+mesh.name+" triangles="+t.Length/3+" edges="+edges.Count+" everyedge2");}
static void Travel(GameObject root){foreach(var t in root.GetComponentsInChildren<Transform>(true)){if(new[]{"REBIRTHCamperBodyModule","REBIRTHCampRoofStations","REBIRTHCampInteriorStations","REBIRTHCampPowerEquipment","REBIRTHCampWalkInColliders","REBIRTHCampStairVisuals"}.Contains(t.name))t.gameObject.SetActive(false);if(t.name=="REBIRTHPickupOnlyPaint"||t.name=="REBIRTHPickupOnlyBodywork")t.gameObject.SetActive(true);}}
static void Render(string name,Vector3 position,Vector3 target,float size){var c=new GameObject("Camera").AddComponent<Camera>();c.transform.position=position;c.transform.LookAt(target);c.orthographic=true;c.orthographicSize=size;c.nearClipPlane=.01f;c.farClipPlane=30;c.backgroundColor=new Color(.15f,.22f,.24f);c.clearFlags=CameraClearFlags.SolidColor;var rt=new RenderTexture(1500,1100,24){antiAliasing=4};c.targetTexture=rt;c.Render();var old=RenderTexture.active;RenderTexture.active=rt;var tex=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);tex.Apply();File.WriteAllBytes(Output+"/"+name+".png",tex.EncodeToPNG());RenderTexture.active=old;Object.DestroyImmediate(tex);rt.Release();Object.DestroyImmediate(rt);Object.DestroyImmediate(c.gameObject);}
static void Views(GameObject root,string state){Travel(root);foreach(int side in new[]{-1,1})Render(state+"-inside-"+side,new Vector3(side*.12f,1.48f,-1.88f),new Vector3(side*.763f,.902f,-2.690f),.28f);Render(state+"-exterior",new Vector3(-5,3,-6),new Vector3(0,.85f,-.35f),2.17f);}
static void RayGrid(GameObject root){int total=0;var jambs=root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("Formed inner rear bed jamb")).ToArray();if(jambs.Length!=2)throw new Exception("Expected exactly2jambs");foreach(var f in jambs)if(f.transform.parent.name!="REBIRTHPickupOnlyPaint"||f.GetComponent<Collider>()!=null)throw new Exception("Jamb paintparent/collider contract");var floor=root.GetComponentsInChildren<Renderer>(true).First(r=>r.name=="Continuous pressed load floor - native tub cutouts");if(floor.sharedMaterial.name!="Dark undyed bed floor"||(floor.sharedMaterial.color-new Color(.08f,.08f,.08f,1)).maxColorComponent>.001f)throw new Exception("Floor material changed");foreach(var f in jambs){var temp=new GameObject("Temporary audit-only ray mesh");temp.layer=29;temp.transform.SetPositionAndRotation(f.transform.position,f.transform.rotation);temp.transform.localScale=f.transform.lossyScale;temp.AddComponent<MeshCollider>().sharedMesh=f.sharedMesh;Physics.SyncTransforms();int side=f.name.EndsWith("-1")?-1:1;for(int y=0;y<=20;y++)for(int x=0;x<=8;x++){float px=side*Mathf.Lerp(.749f,.778f,x/8f),py=Mathf.Lerp(.690f,1.12f,y/20f);if(!Physics.Raycast(new Vector3(px,py,-2.60f),Vector3.back,out _,.18f,1<<29,QueryTriggerInteraction.Ignore))throw new Exception("Rear jamb ray hole "+side+" "+px+" "+py);total++;}Object.DestroyImmediate(temp);}report.AppendLine("RAYGRID "+total+"/"+total+" pass through previously open gap; y.690..1.120,absx.749...778; physical prefab unchanged");}
public static string Verify(GameObject root){Travel(root);RayGrid(root);foreach(var f in root.GetComponentsInChildren<MeshFilter>(true).Where(f=>f.name.StartsWith("Formed inner rear bed jamb")))ValidateClosed(f.sharedMesh);return report.ToString();}
