Views(root,"before");var paint=root.transform.Find("GameObject/M/VisualBody/80sCamperTruck/body/REBIRTHPickupOnlyPaint");var material=paint.GetComponentInChildren<Renderer>(true).sharedMaterial;foreach(int side in new[]{-1,1}){var mesh=Jamb(side,paint);ValidateClosed(mesh);string path=Folder+"/rear_inner_jamb_"+side+".asset";var stale="Assets/REBIRTHApprovedPickupProduction_20261020/rear_inner_jamb_"+side+".asset";if(AssetDatabase.LoadAssetAtPath<Mesh>(stale))AssetDatabase.DeleteAsset(stale);if(AssetDatabase.LoadAssetAtPath<Mesh>(path))AssetDatabase.DeleteAsset(path);AssetDatabase.CreateAsset(mesh,path);var go=new GameObject("Formed inner rear bed jamb "+side);go.transform.SetParent(paint,false);go.layer=paint.gameObject.layer;go.tag="LOD";go.AddComponent<MeshFilter>().sharedMesh=mesh;go.AddComponent<MeshRenderer>().sharedMaterial=material;var block=new MaterialPropertyBlock();block.SetColor("_Color",new Color(185,135,65,1));go.GetComponent<Renderer>().SetPropertyBlock(block);}
